use axum::extract::State;
use axum::Json;
use serde::{Deserialize, Serialize};
use uuid::Uuid;

use crate::auth::jwt::AuthUser;
use crate::birds;
use crate::error::{AppError, AppResult};
use crate::physics::engine::{score_shots, ShotInput};
use crate::physics::level;
use crate::state::AppState;

/// The client submits only shot *inputs*. The server computes the real score.
#[derive(Deserialize)]
pub struct SubmitRequest {
    pub level: i32,
    pub shots: Vec<ShotInput>,
}

#[derive(Serialize)]
pub struct SubmitResponse {
    pub score: i32,
    pub pigs_destroyed: usize,
    pub blocks_destroyed: usize,
    pub best_score: i32,
    pub newly_unlocked: Vec<String>,
}

const MAX_SHOTS: usize = 20;

pub async fn submit(
    State(state): State<AppState>,
    user: AuthUser,
    Json(req): Json<SubmitRequest>,
) -> AppResult<Json<SubmitResponse>> {
    if req.shots.is_empty() {
        return Err(AppError::Validation("no shots submitted".into()));
    }
    if req.shots.len() > MAX_SHOTS {
        return Err(AppError::Validation("too many shots".into()));
    }
    for s in &req.shots {
        if !s.power.is_finite() || !s.angle.is_finite() {
            return Err(AppError::Validation("invalid shot values".into()));
        }
        if birds::find(&s.bird).is_none() {
            return Err(AppError::Validation(format!("unknown bird: {}", s.bird)));
        }
    }

    let lvl = level::by_id(req.level)
        .ok_or_else(|| AppError::Validation("unknown level".into()))?;

    // Best score BEFORE this run (to detect newly unlocked birds).
    let prev_best = fetch_best_score(&state, user.user_id).await?;

    // Authoritative simulation.
    let result = score_shots(lvl, &req.shots);

    let primary_bird = req
        .shots
        .first()
        .map(|s| s.bird.clone())
        .unwrap_or_else(|| "red".into());

    sqlx::query(
        r#"INSERT INTO scores (user_id, score, level, bird_variant)
           VALUES ($1, $2, $3, $4)"#,
    )
    .bind(user.user_id)
    .bind(result.score)
    .bind(req.level)
    .bind(&primary_bird)
    .execute(&state.pool)
    .await?;

    let new_best = prev_best.max(result.score);

    let newly_unlocked: Vec<String> = birds::BIRDS
        .iter()
        .filter(|b| {
            new_best >= b.unlock_score && prev_best < b.unlock_score && b.unlock_score > 0
        })
        .map(|b| b.id.to_string())
        .collect();

    Ok(Json(SubmitResponse {
        score: result.score,
        pigs_destroyed: result.pigs_destroyed,
        blocks_destroyed: result.blocks_destroyed,
        best_score: new_best,
        newly_unlocked,
    }))
}

#[derive(Serialize)]
pub struct LeaderboardEntry {
    pub rank: i64,
    pub username: String,
    pub best_score: i32,
}

#[derive(sqlx::FromRow)]
struct LeaderboardRow {
    username: String,
    best: i32,
}

pub async fn leaderboard(
    State(state): State<AppState>,
) -> AppResult<Json<Vec<LeaderboardEntry>>> {
    let rows: Vec<LeaderboardRow> = sqlx::query_as(
        r#"SELECT u.username AS username, MAX(s.score) AS best
           FROM scores s JOIN users u ON u.id = s.user_id
           GROUP BY u.username
           ORDER BY best DESC
           LIMIT 20"#,
    )
    .fetch_all(&state.pool)
    .await?;

    let entries = rows
        .into_iter()
        .enumerate()
        .map(|(i, r)| LeaderboardEntry {
            rank: (i + 1) as i64,
            username: r.username,
            best_score: r.best,
        })
        .collect();

    Ok(Json(entries))
}

#[derive(Serialize, sqlx::FromRow)]
pub struct MyScore {
    pub score: i32,
    pub level: i32,
    pub bird_variant: String,
    pub created_at: chrono::DateTime<chrono::Utc>,
}

#[derive(Serialize)]
pub struct MyScoresResponse {
    pub best_score: i32,
    pub scores: Vec<MyScore>,
}

pub async fn my_scores(
    State(state): State<AppState>,
    user: AuthUser,
) -> AppResult<Json<MyScoresResponse>> {
    let best = fetch_best_score(&state, user.user_id).await?;
    let scores: Vec<MyScore> = sqlx::query_as(
        r#"SELECT score, level, bird_variant, created_at
           FROM scores WHERE user_id = $1
           ORDER BY created_at DESC LIMIT 50"#,
    )
    .bind(user.user_id)
    .fetch_all(&state.pool)
    .await?;

    Ok(Json(MyScoresResponse {
        best_score: best,
        scores,
    }))
}

async fn fetch_best_score(state: &AppState, user_id: Uuid) -> AppResult<i32> {
    let best: i32 = sqlx::query_scalar(
        r#"SELECT COALESCE(MAX(score), 0) FROM scores WHERE user_id = $1"#,
    )
    .bind(user_id)
    .fetch_one(&state.pool)
    .await?;
    Ok(best)
}

