import Matter from "matter-js";
import type { Bird } from "../api/types";
import { hasActiveAbility } from "./birds";
import type { Level } from "./levels";

const MAX_LAUNCH_SPEED = 70; // must match backend engine.rs MAX_LAUNCH_SPEED
const SCALE = 8; // world-units -> pixels

export interface ShotRecord {
  bird: string;
  angle: number;
  power: number;
  ability_tap: number | null;
}

interface EngineCallbacks {
  onShotComplete: (shots: ShotRecord[]) => void;
  onStatus: (msg: string) => void;
}

export class GameEngine {
  private engine: Matter.Engine;
  private render: Matter.Render;
  private runner: Matter.Runner;
  private level: Level;
  private canvas: HTMLCanvasElement;
  private callbacks: EngineCallbacks;

  private currentBird: Bird;
  private shots: ShotRecord[] = [];
  private maxShots = 5;

  private aiming = false;
  private aimStart = { x: 0, y: 0 };
  private aimCurrent = { x: 0, y: 0 };

  private activeBirdBody: Matter.Body | null = null;
  private launchTime = 0;
  private abilityUsed = false;

  constructor(
    canvas: HTMLCanvasElement,
    level: Level,
    bird: Bird,
    callbacks: EngineCallbacks,
  ) {
    this.canvas = canvas;
    this.level = level;
    this.currentBird = bird;
    this.callbacks = callbacks;

    this.engine = Matter.Engine.create();
    this.engine.gravity.y = 1; // matter uses its own units; visual only

    const width = level.width * SCALE;
    const height = level.height * SCALE;

    this.render = Matter.Render.create({
      canvas,
      engine: this.engine,
      options: {
        width,
        height,
        wireframes: false,
        background: "#8ecae6",
      },
    });

    this.runner = Matter.Runner.create();

    this.buildWorld();
    this.attachInput();

    Matter.Render.run(this.render);
    Matter.Runner.run(this.runner, this.engine);
  }

  // Convert world coords (origin bottom-left, +y up) to canvas px (origin top-left, +y down).
  private toPx(x: number, y: number) {
    return { x: x * SCALE, y: (this.level.height - y) * SCALE };
  }

  private buildWorld() {
    const w = this.level.width * SCALE;
    const h = this.level.height * SCALE;

    // Ground
    const ground = Matter.Bodies.rectangle(w / 2, h - 4, w, 8, {
      isStatic: true,
      render: { fillStyle: "#6a994e" },
    });

    const bodies: Matter.Body[] = [ground];

    for (const b of this.level.blocks) {
      const c = this.toPx(b.x, b.y + b.h / 2);
      bodies.push(
        Matter.Bodies.rectangle(c.x, c.y, b.w * SCALE, b.h * SCALE, {
          render: { fillStyle: "#b08968" },
        }),
      );
    }

    for (const p of this.level.pigs) {
      const c = this.toPx(p.x, p.y);
      bodies.push(
        Matter.Bodies.circle(c.x, c.y, p.r * SCALE, {
          render: { fillStyle: "#52b788" },
        }),
      );
    }

    Matter.Composite.add(this.engine.world, bodies);
  }

  private slingPx() {
    return this.toPx(this.level.slingshotX, this.level.slingshotY);
  }

  private spawnBirdAtSling() {
    const s = this.slingPx();
    const body = Matter.Bodies.circle(s.x, s.y, 1.2 * SCALE, {
      isStatic: true,
      render: { fillStyle: this.currentBird.color },
      label: "bird",
    });
    Matter.Composite.add(this.engine.world, body);
    this.activeBirdBody = body;
    this.abilityUsed = false;
  }

  private attachInput() {
    const onDown = (e: MouseEvent) => {
      if (!this.activeBirdBody) return;
      // If bird already launched and has an active ability, a click triggers it.
      if (
        !this.activeBirdBody.isStatic &&
        hasActiveAbility(this.currentBird.ability) &&
        !this.abilityUsed
      ) {
        this.triggerAbility();
        return;
      }
      if (!this.activeBirdBody.isStatic) return;
      this.aiming = true;
      const r = this.canvas.getBoundingClientRect();
      this.aimStart = { x: e.clientX - r.left, y: e.clientY - r.top };
      this.aimCurrent = { ...this.aimStart };
    };

    const onMove = (e: MouseEvent) => {
      if (!this.aiming) return;
      const r = this.canvas.getBoundingClientRect();
      this.aimCurrent = { x: e.clientX - r.left, y: e.clientY - r.top };
    };

    const onUp = () => {
      if (!this.aiming || !this.activeBirdBody) return;
      this.aiming = false;
      this.launch();
    };

    this.canvas.addEventListener("mousedown", onDown);
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);

    this._detach = () => {
      this.canvas.removeEventListener("mousedown", onDown);
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
    };
  }

  private _detach: () => void = () => {};

  private launch() {
    if (!this.activeBirdBody) return;
    const sling = this.slingPx();
    // Drag vector: slingshot pulls back from release point toward sling.
    const dx = sling.x - this.aimCurrent.x;
    const dy = sling.y - this.aimCurrent.y;
    const dragPx = Math.hypot(dx, dy);
    const maxDragPx = 20 * SCALE;
    const power = Math.min(dragPx / maxDragPx, 1);
    // Angle in world coords: +y is up, so invert dy.
    const angle = Math.atan2(-dy * -1, dx); // launch toward drag direction
    const worldAngle = Math.atan2(dy, dx); // canvas y-down

    // Convert canvas-y-down angle to world-y-up angle for the backend.
    const backendAngle = Math.atan2(-dy, dx);

    // Apply velocity to the matter body (visual).
    const speed = MAX_LAUNCH_SPEED * power * this.currentBird.power;
    Matter.Body.setStatic(this.activeBirdBody, false);
    Matter.Body.setVelocity(this.activeBirdBody, {
      x: Math.cos(worldAngle) * speed,
      y: Math.sin(worldAngle) * speed,
    });

    void angle;

    this.launchTime = performance.now();

    this.shots.push({
      bird: this.currentBird.id,
      angle: backendAngle,
      power,
      ability_tap: null,
    });

    this.callbacks.onStatus(
      `Launched ${this.currentBird.name} (power ${(power * 100).toFixed(0)}%)`,
    );

    // After the shot settles, prepare the next shot or end the round.
    window.setTimeout(() => this.endShot(), 6000);
  }

  private triggerAbility() {
    if (!this.activeBirdBody || this.abilityUsed) return;
    this.abilityUsed = true;
    const t = (performance.now() - this.launchTime) / 1000;
    // Record the ability tap time on the latest shot.
    const last = this.shots[this.shots.length - 1];
    if (last) last.ability_tap = t;

    const body = this.activeBirdBody;
    const v = body.velocity;
    switch (this.currentBird.ability) {
      case "dash": {
        Matter.Body.setVelocity(body, { x: v.x * 1.6 + 10, y: v.y });
        break;
      }
      case "egg_drop": {
        Matter.Body.setVelocity(body, { x: v.x, y: v.y + 30 });
        break;
      }
      case "explode": {
        // Visual blast: push nearby bodies.
        const bodies = Matter.Composite.allBodies(this.engine.world);
        for (const b of bodies) {
          if (b === body || b.isStatic) continue;
          const dx = b.position.x - body.position.x;
          const dy = b.position.y - body.position.y;
          const d = Math.hypot(dx, dy);
          if (d < 10 * SCALE && d > 0.1) {
            const f = (1 - d / (10 * SCALE)) * 0.4;
            Matter.Body.applyForce(b, b.position, {
              x: (dx / d) * f,
              y: (dy / d) * f,
            });
          }
        }
        break;
      }
      case "split": {
        Matter.Body.setVelocity(body, { x: v.x * 1.2, y: v.y - 10 });
        break;
      }
      default:
        break;
    }
    this.callbacks.onStatus(`${this.currentBird.name} ability!`);
  }

  private endShot() {
    if (this.activeBirdBody) {
      Matter.Composite.remove(this.engine.world, this.activeBirdBody);
      this.activeBirdBody = null;
    }
    if (this.shots.length >= this.maxShots) {
      this.finishRound();
    } else {
      this.spawnBirdAtSling();
      this.callbacks.onStatus(
        `Shot ${this.shots.length + 1}/${this.maxShots}. Aim and release.`,
      );
    }
  }

  // Called externally to begin the round once a bird is selected.
  start() {
    this.spawnBirdAtSling();
    this.callbacks.onStatus(
      `Shot 1/${this.maxShots}. Drag back from the slingshot and release.`,
    );
  }

  setBird(bird: Bird) {
    this.currentBird = bird;
    if (this.activeBirdBody && this.activeBirdBody.isStatic) {
      this.activeBirdBody.render.fillStyle = bird.color;
    }
  }

  // End the round early (e.g., player presses "Done").
  finishRound() {
    this.callbacks.onShotComplete([...this.shots]);
  }

  getAimState() {
    return {
      aiming: this.aiming,
      start: this.aimStart,
      current: this.aimCurrent,
      sling: this.slingPx(),
    };
  }

  destroy() {
    this._detach();
    Matter.Render.stop(this.render);
    Matter.Runner.stop(this.runner);
    Matter.Composite.clear(this.engine.world, false);
    Matter.Engine.clear(this.engine);
    if (this.render.canvas) {
      this.render.textures = {};
    }
  }
}

