import { useEffect, useRef, useState } from "react";
import { api } from "../api/client";
import type { Bird, SubmitResponse } from "../api/types";
import { ABILITY_LABEL, FALLBACK_BIRDS } from "../game/birds";
import { GameEngine, type ShotRecord } from "../game/engine";
import { LEVEL_ONE } from "../game/levels";

export default function Game() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const engineRef = useRef<GameEngine | null>(null);
  const [birds, setBirds] = useState<Bird[]>(FALLBACK_BIRDS);
  const [selected, setSelected] = useState<Bird>(FALLBACK_BIRDS[0]);
  const [status, setStatus] = useState("Loading…");
  const [result, setResult] = useState<SubmitResponse | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Load bird catalog (with unlock state) from the server.
  useEffect(() => {
    api
      .birds()
      .then((bs) => {
        setBirds(bs);
        const firstUnlocked = bs.find((b) => b.unlocked) ?? bs[0];
        setSelected(firstUnlocked);
      })
      .catch(() => setBirds(FALLBACK_BIRDS));
  }, []);

  // (Re)create the engine when the canvas is ready.
  useEffect(() => {
    if (!canvasRef.current) return;
    const engine = new GameEngine(canvasRef.current, LEVEL_ONE, selected, {
      onStatus: setStatus,
      onShotComplete: handleShotComplete,
    });
    engineRef.current = engine;
    engine.start();
    return () => {
      engine.destroy();
      engineRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Keep the live bird in sync with the selection.
  useEffect(() => {
    engineRef.current?.setBird(selected);
  }, [selected]);

  async function handleShotComplete(shots: ShotRecord[]) {
    if (shots.length === 0) return;
    setSubmitting(true);
    setError(null);
    try {
      const res = await api.submitScore(LEVEL_ONE.id, shots);
      setResult(res);
      setStatus(`Round over! Server scored ${res.score} points.`);
      // Refresh unlock state.
      const bs = await api.birds();
      setBirds(bs);
    } catch (e) {
      setError(e instanceof Error ? e.message : "failed to submit score");
    } finally {
      setSubmitting(false);
    }
  }

  function finishNow() {
    engineRef.current?.finishRound();
  }

  function playAgain() {
    setResult(null);
    if (canvasRef.current) {
      engineRef.current?.destroy();
      const engine = new GameEngine(canvasRef.current, LEVEL_ONE, selected, {
        onStatus: setStatus,
        onShotComplete: handleShotComplete,
      });
      engineRef.current = engine;
      engine.start();
    }
  }

  return (
    <div className="game-layout">
      <div className="game-main">
        <div className="status-bar">{status}</div>
        <canvas ref={canvasRef} className="game-canvas" />
        <div className="game-controls">
          <button onClick={finishNow} disabled={submitting}>
            {submitting ? "Scoring…" : "Finish round"}
          </button>
          {result && <button onClick={playAgain}>Play again</button>}
        </div>
        {error && <div className="error">{error}</div>}
        {result && (
          <div className="result-card">
            <h3>Server score: {result.score}</h3>
            <p>
              Pigs destroyed: {result.pigs_destroyed} · Blocks destroyed:{" "}
              {result.blocks_destroyed}
            </p>
            <p>Your best: {result.best_score}</p>
            {result.newly_unlocked.length > 0 && (
              <p className="unlock">
                🎉 Unlocked:{" "}
                {result.newly_unlocked
                  .map((id) => birds.find((b) => b.id === id)?.name ?? id)
                  .join(", ")}
              </p>
            )}
          </div>
        )}
      </div>

      <aside className="bird-picker">
        <h3>Choose your bird</h3>
        {birds.map((b) => (
          <button
            key={b.id}
            className={`bird-chip ${selected.id === b.id ? "selected" : ""} ${
              b.unlocked ? "" : "locked"
            }`}
            onClick={() => b.unlocked && setSelected(b)}
            disabled={!b.unlocked}
            title={b.unlocked ? b.description : `Unlock at ${b.unlock_score}`}
          >
            <span className="swatch" style={{ background: b.color }} />
            <span className="bird-info">
              <strong>{b.name}</strong>
              <small>{ABILITY_LABEL[b.ability]}</small>
              {!b.unlocked && (
                <small className="lock">🔒 {b.unlock_score} pts</small>
              )}
            </span>
          </button>
        ))}
        <p className="hint">
          Drag back from the slingshot and release to launch. Click again
          mid-flight to trigger a bird's ability.
        </p>
      </aside>
    </div>
  );
}

