import { useEffect, useState } from "react";
import { api } from "../api/client";
import type { LeaderboardEntry, MyScoresResponse } from "../api/types";

export default function Leaderboard() {
  const [entries, setEntries] = useState<LeaderboardEntry[]>([]);
  const [mine, setMine] = useState<MyScoresResponse | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    api
      .leaderboard()
      .then(setEntries)
      .catch((e) =>
        setError(e instanceof Error ? e.message : "failed to load leaderboard"),
      );
    api
      .myScores()
      .then(setMine)
      .catch(() => {
        /* not logged in — ignore */
      });
  }, []);

  return (
    <div className="board-page">
      <section>
        <h2>🏆 Global leaderboard</h2>
        {error && <div className="error">{error}</div>}
        <table className="board-table">
          <thead>
            <tr>
              <th>#</th>
              <th>Player</th>
              <th>Best score</th>
            </tr>
          </thead>
          <tbody>
            {entries.map((e) => (
              <tr key={e.rank}>
                <td>{e.rank}</td>
                <td>{e.username}</td>
                <td>{e.best_score}</td>
              </tr>
            ))}
            {entries.length === 0 && (
              <tr>
                <td colSpan={3}>No scores yet. Be the first!</td>
              </tr>
            )}
          </tbody>
        </table>
      </section>

      {mine && (
        <section>
          <h2>Your history (best: {mine.best_score})</h2>
          <table className="board-table">
            <thead>
              <tr>
                <th>Score</th>
                <th>Bird</th>
                <th>Level</th>
                <th>When</th>
              </tr>
            </thead>
            <tbody>
              {mine.scores.map((s, i) => (
                <tr key={i}>
                  <td>{s.score}</td>
                  <td>{s.bird_variant}</td>
                  <td>{s.level}</td>
                  <td>{new Date(s.created_at).toLocaleString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>
      )}
    </div>
  );
}

import { useEffect } from "react";
import {
  Link,
  Navigate,
  Route,
  Routes,
  useLocation,
} from "react-router-dom";
import Game from "./pages/Game";
import Leaderboard from "./pages/Leaderboard";
import Login from "./pages/Login";
import Register from "./pages/Register";
import { useAuth } from "./store/auth";

function RequireAuth({ children }: { children: JSX.Element }) {
  const user = useAuth((s) => s.user);
  const initialized = useAuth((s) => s.initialized);
  const location = useLocation();
  if (!initialized) return <div className="loading">Loading…</div>;
  if (!user) return <Navigate to="/login" state={{ from: location }} replace />;
  return children;
}

export default function App() {
  const user = useAuth((s) => s.user);
  const init = useAuth((s) => s.init);
  const logout = useAuth((s) => s.logout);

  useEffect(() => {
    void init();
  }, [init]);

  return (
    <div className="app">
      <header className="nav">
        <Link to="/" className="brand">
          🐦 Angry Bird
        </Link>
        <nav>
          <Link to="/">Play</Link>
          <Link to="/leaderboard">Leaderboard</Link>
          {user ? (
            <>
              <span className="user">{user.username}</span>
              <button className="link-btn" onClick={logout}>
                Log out
              </button>
            </>
          ) : (
            <Link to="/login">Log in</Link>
          )}
        </nav>
      </header>

      <main>
        <Routes>
          <Route
            path="/"
            element={
              <RequireAuth>
                <Game />
              </RequireAuth>
            }
          />
          <Route path="/leaderboard" element={<Leaderboard />} />
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </main>
    </div>
  );
}

