/// <reference types="vite/client" />

interface ImportMetaEnv {
  readonly VITE_API_BASE_URL: string;
}

interface ImportMeta {
  readonly env: ImportMetaEnv;
}

:root {
  --sky: #8ecae6;
  --sky-deep: #219ebc;
  --sun: #ffb703;
  --accent: #fb8500;
  --ink: #023047;
  --panel: #ffffff;
  --danger: #d62828;
  font-family: "Segoe UI", system-ui, sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: linear-gradient(180deg, var(--sky) 0%, #e9f5ff 100%);
  color: var(--ink);
  min-height: 100vh;
}

.app {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 16px 48px;
}

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
  flex-wrap: wrap;
  gap: 12px;
}

.brand {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--ink);
  text-decoration: none;
}

.nav nav {
  display: flex;
  align-items: center;
  gap: 16px;
}

.nav a {
  color: var(--ink);
  text-decoration: none;
  font-weight: 600;
}

.nav a:hover {
  color: var(--accent);
}

.user {
  font-weight: 700;
  color: var(--sky-deep);
}

.link-btn {
  background: none;
  border: none;
  color: var(--danger);
  cursor: pointer;
  font-weight: 600;
  font-size: 1rem;
}

button {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 10px 16px;
  font-weight: 700;
  cursor: pointer;
  transition: transform 0.05s ease, background 0.15s ease;
}

button:hover:not(:disabled) {
  background: var(--sun);
}

button:active:not(:disabled) {
  transform: translateY(1px);
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Auth pages */
.auth-page {
  display: flex;
  justify-content: center;
  padding-top: 48px;
}

.auth-card {
  background: var(--panel);
  padding: 32px;
  border-radius: 16px;
  box-shadow: 0 10px 30px rgba(2, 48, 71, 0.15);
  width: 360px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.auth-card h2 {
  margin: 0 0 8px;
}

.auth-card label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-weight: 600;
}

.auth-card input {
  padding: 10px;
  border: 2px solid #cfe8f5;
  border-radius: 8px;
  font-size: 1rem;
}

.auth-card input:focus {
  outline: none;
  border-color: var(--sky-deep);
}

.error {
  background: #ffe5e5;
  color: var(--danger);
  padding: 8px 12px;
  border-radius: 8px;
  font-weight: 600;
}

/* Game layout */
.game-layout {
  display: grid;
  grid-template-columns: 1fr 280px;
  gap: 20px;
  align-items: start;
}

.game-main {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.status-bar {
  background: var(--ink);
  color: #fff;
  padding: 10px 14px;
  border-radius: 8px;
  font-weight: 600;
}

.game-canvas {
  width: 100%;
  border-radius: 12px;
  border: 4px solid var(--ink);
  background: var(--sky);
  cursor: crosshair;
}

.game-controls {
  display: flex;
  gap: 12px;
}

.result-card {
  background: var(--panel);
  border-radius: 12px;
  padding: 16px 20px;
  box-shadow: 0 6px 20px rgba(2, 48, 71, 0.12);
}

.result-card h3 {
  margin: 0 0 8px;
  color: var(--accent);
}

.unlock {
  color: var(--sky-deep);
  font-weight: 700;
}

/* Bird picker */
.bird-picker {
  background: var(--panel);
  border-radius: 12px;
  padding: 16px;
  box-shadow: 0 6px 20px rgba(2, 48, 71, 0.12);
}

.bird-picker h3 {
  margin: 0 0 12px;
}

.bird-chip {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  background: #f4faff;
  color: var(--ink);
  border: 2px solid transparent;
  border-radius: 10px;
  padding: 10px;
  margin-bottom: 8px;
  text-align: left;
}

.bird-chip:hover:not(:disabled) {
  background: #e3f3ff;
}

.bird-chip.selected {
  border-color: var(--accent);
  background: #fff3e0;
}

.bird-chip.locked {
  opacity: 0.6;
}

.swatch {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 2px solid rgba(0, 0, 0, 0.2);
  flex-shrink: 0;
}

.bird-info {
  display: flex;
  flex-direction: column;
}

.bird-info small {
  font-weight: 500;
  opacity: 0.8;
}

.bird-info .lock {
  color: var(--danger);
  font-weight: 700;
}

.hint {
  font-size: 0.85rem;
  opacity: 0.8;
  margin-top: 12px;
}

/* Leaderboard */
.board-page {
  display: flex;
  flex-direction: column;
  gap: 32px;
}

.board-table {
  width: 100%;
  border-collapse: collapse;
  background: var(--panel);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 6px 20px rgba(2, 48, 71, 0.12);
}

.board-table th,
.board-table td {
  padding: 12px 16px;
  text-align: left;
  border-bottom: 1px solid #eef5fa;
}

.board-table th {
  background: var(--ink);
  color: #fff;
}

.board-table tr:nth-child(even) td {
  background: #f7fbfe;
}

.loading {
  padding: 48px;
  text-align: center;
  font-weight: 600;
}

/* Responsive */
@media (max-width: 860px) {
  .game-layout {
    grid-template-columns: 1fr;
  }
}

