/* Leaderboard */
.board-page {
  display: flex;
  flex-direction: column;
  gap: 32px;
}

.board-table {
  width: 100%;
  border-collapse: collapse;
  background: var(--panel);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 6px 20px rgba(2, 48, 71, 0.12);
}

.board-table th,
.board-table td {
  padding: 12px 16px;
  text-align: left;
  border-bottom: 1px solid #eef5fa;
}

.board-table th {
  background: var(--ink);
  color: #fff;
}

.board-table tr:nth-child(even) td {
  background: #f7fbfe;
}

.loading {
  padding: 48px;
  text-align: center;
  font-weight: 600;
}

/* Responsive */
@media (max-width: 860px) {
  .game-layout {
    grid-template-columns: 1fr;
  }
}

